function e(i){if(!i)return"-";const t=new Date(i);return isNaN(t.getTime())?i:t.toLocaleString("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit"})}function n(i){if(!i)return"-";const t=new Date(i);return isNaN(t.getTime())?i:t.toLocaleDateString("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit"})}export{e as a,n as f};
